	INSERT INTO @MappingReportCode(OCode,NCode)	VALUES('A11','2')
	INSERT INTO @MappingReportCode(OCode,NCode)	VALUES('A12','3')
	INSERT INTO @MappingReportCode(OCode,NCode)	VALUES('A13','4')
