p_Report_DataImports_ImportDatas_Industr.sql:
ALTER PROCEDURE dbo.p_Report_DataImports_ImportDatas_IndustryScope
 @EnterpriseId int,@ForMonth datetime,@TypeReport int,@TypeReportName nvarchar(1500),
 @DataReport dbo.DataReportWithIndexLevel READONLY,@ReportFile nvarchar(1500),@Reason nvarchar(1500),@ImportBy varchar(500),@IndustryUserName varchar(255)
AS BEGIN
 SET NOCOUNT ON;
 IF @ImportBy<>@IndustryUserName OR @ImportBy IS NULL THROW 50112,'Report actor mismatch',1;
 IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.f_Report_IndustryEnterprises(@IndustryUserName) WHERE EnterpriseId=@EnterpriseId)
  THROW 50112,'Enterprise access denied',1;
 IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Users u
 JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_UserRoles ur ON ur.UserId=u.UserId
 JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Roles r ON r.RoleId=ur.RoleId AND r.IsDeleted=0
 JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Permissions p ON p.RoleId=r.RoleId
 JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions f ON f.FunctionId=p.FunctionId AND f.IsDeleted=0
 WHERE u.UserName=@IndustryUserName AND u.IsActive=1 AND u.IsDeleted=0 AND ISNULL(u.IsLocked,0)=0
 AND f.Area='Report' AND f.Name='Import' AND p.Action IN('Add','Edit')) THROW 50112,'Report operation denied',1;
 DECLARE @Result int;
 EXEC @Result=dbo.p_Report_DataImports_ImportDatas @EnterpriseId,@ForMonth,@TypeReport,@TypeReportName,@DataReport,@ReportFile,@Reason,@ImportBy;
 RETURN @Result;
END;

